import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Dyi9RH6t.js";var i=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{"title":"Troubleshooting"},"headers":[],"relativePath":"guides/the-manual/testing/troubleshooting.md","filePath":"guides/the-manual/testing/troubleshooting.md"}`),a={name:`guides/the-manual/testing/troubleshooting.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>Each section starts with what holodeck prints. Search this page for the text you have.</p><h2 id="a-mocked-request-failed-with-a-400" tabindex="-1">A mocked request failed with a 400 <a class="header-anchor" href="#a-mocked-request-failed-with-a-400" aria-label="Permalink to “A mocked request failed with a 400”">​</a></h2><p>A missing or mismatched fixture is a <code>400</code> from the mock server, and what the terminal shows depends on whether the test lets that error escape.</p><p>A test that lets it escape prints the request and, under it, the server&#39;s explanation.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>💥 Fail Unexpected Test Failure: [400 Bad Request] POST (cors) - https://localhost:7358/api/user/ops/bulk.create</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No meta was found for POST https://localhost:7358/api/user/ops/bulk.create. The expected cacheKey was /path/to/tests/json-api/.mock-cache/36ff0af3/POST::api_user_ops_bulk.create::0/f6c45fa65d57493c31a4f1b85eddcf6f. You may need to record a mock for this request.</span></span></code></pre></div><p>The second paragraph is the <code>detail</code> of the server&#39;s <code>MOCK_NOT_FOUND</code> response. <code>MockServerHandler</code> lifts it into the thrown error, with holodeck&#39;s own <code>__xTestId</code> query stripped out of the URL, so it reaches the terminal and the CI log. Searching a failed run for <code>No meta was found</code> finds it.</p><p>A test that catches the error and asserts against it prints only the assertions that failed. The explanation is still on the caught error, as <code>error.content</code>, but nothing prints it.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>💥 Failed: 0ms Integration | @ember-data/json-api Cach.put(&lt;ErrorDocument&gt;):Useful errors are propagated by the CacheHandler</span></span>
<span class="line"><span>	✅ Pass The error is an AggregateError</span></span>
<span class="line"><span>	💥 Fail The error message is correct</span></span>
<span class="line"><span>	💥 Fail The error status is correct</span></span></code></pre></div><p>Diagnostic prints the test id with every failure, whichever shape you get.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>open test locally: https://localhost:7357?testId=546c9e3a</span></span></code></pre></div><p>That id is the fixture directory. Look in <code>.mock-cache/546c9e3a/</code> and you are in the right place. Open the printed URL to run the one test in a browser and read the failed request in the network panel, where the same <code>MOCK_NOT_FOUND</code> payload is the response body.</p><p>Compare the <code>cacheKey</code> in the message against what is on disk. The part that differs tells you which half of the mock is wrong.</p><ul><li>The directory is missing entirely. The fixture was never committed, or you are running in replay mode against a test you have not recorded yet.</li><li>The URL segment differs. The mock URL and the request URL are not the same string. Query encoding is the usual cause. See <a href="./writing-mocks#write-the-url-the-way-the-server-will-see-it">Write the URL the way the server will see it</a>.</li><li>The trailing number differs. The test made more requests to that URL than it declared mocks for, or declared them in a different order.</li><li>The file name is a hash rather than <code>res</code>, and no file of that name exists. The <code>body</code> option and the real request body are not the same string. Open the recorded <code>.meta.json</code> and look at <code>requestBody</code>. A correctly recorded body-matched mock stores an escaped JSON <strong>string</strong>. An object there means someone passed an object literal to the mock.</li></ul><h2 id="the-test-declared-a-mock-it-never-requested" tabindex="-1">The test declared a mock it never requested <a class="header-anchor" href="#the-test-declared-a-mock-it-never-requested" aria-label="Permalink to “The test declared a mock it never requested”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>💥 Fail Unexpected Test Failure in afterEach: Holodeck: this test declared mocks it never requested.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	GET users/never-requested (mocked 1, requested 0)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A mock that is never requested proves nothing. Remove it, or make the request it describes.</span></span></code></pre></div><p>When <code>setTestId(this, null)</code> runs from <code>afterEach</code>, holodeck compares the mocks the test declared against the requests it made, per method and URL, and fails the test over any mock left over. The report is added alongside the body&#39;s own assertions rather than in place of them, so a test whose body already failed shows both. It fires in record and replay alike.</p><p>Read the two counts. <code>mocked 1, requested 0</code> is a mock the code under test never asked for. Delete it, or fix the test so the request happens. <code>mocked 2, requested 1</code> is one declaration too many for a URL the test does hit. See <a href="./writing-mocks#mock-the-same-url-more-than-once">Mock the same URL more than once</a>.</p><p>An error earlier in the test body, including a failed recording, also leaves its mock unrequested, so this report often follows another failure. Fix the first one and this one goes with it.</p><h2 id="holodeck-failed-to-record" tabindex="-1">Holodeck failed to record <a class="header-anchor" href="#holodeck-failed-to-record" aria-label="Permalink to “Holodeck failed to record”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>💥 Fail Unexpected Test Failure: MockError: Holodeck failed to record GET users/1 (500 ). Cannot read properties of undefined (reading &#39;Content-Type&#39;)</span></span></code></pre></div><p>While recording, each mock helper posts its scaffold to the server, and throws when the server rejects it. The message carries the status and then the server&#39;s own explanation. The status text is blank because the server speaks HTTP/2, which has none.</p><p>In the example the scaffold was built by hand with <code>mock</code> and left out <code>headers</code>, which the six helpers always supply. A fixture the server cannot write, because <code>.mock-cache</code> is not writable or the disk is full, reports the filesystem error in the same place. Replay posts nothing, so this only appears in a recording run.</p><h2 id="the-test-id-is-missing" tabindex="-1">The test id is missing <a class="header-anchor" href="#the-test-id-is-missing" aria-label="Permalink to “The test id is missing”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MockServerHandler is not configured with a testId. Use setTestId to set the testId for each test</span></span></code></pre></div><p>Holodeck looks the test up by object identity, and it was handed an object it does not know.</p><p>Check three things in this order. The global hooks that call <code>setTestId</code> are installed. The object passed to <code>new MockServerHandler(...)</code> is the same test context <code>setTestId</code> received. The test body is a <code>function</code> rather than an arrow function, so <code>this</code> is the test context at all.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Cannot call &quot;mock&quot; before configuring a testId. Use setTestId to set the testId for each test</span></span></code></pre></div><p>Same cause, reported from a mock helper instead of from the request handler.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MockServerHandler is already configured with a testId.</span></span></code></pre></div><p><code>setTestId</code> ran twice for one test context. A second <code>setupGlobalHooks</code> block or a stray per-test call is the usual reason.</p><h2 id="the-request-never-reached-the-handler" tabindex="-1">The request never reached the handler <a class="header-anchor" href="#the-request-never-reached-the-handler" aria-label="Permalink to “The request never reached the handler”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MISSING_X_TEST_ID_HEADER</span></span></code></pre></div><p>The server received a request carrying no <code>__xTestId</code> query parameter, which means the request did not go through <code>MockServerHandler</code>. The code keeps its historical name, but the message names the query parameter and says what to do. Put the handler in the chain ahead of <code>Fetch</code>, and check that the code under test goes through that <code>RequestManager</code> rather than calling <code>fetch</code> directly.</p><h2 id="the-certificate-is-missing" tabindex="-1">The certificate is missing <a class="header-anchor" href="#the-certificate-is-missing" aria-label="Permalink to “The certificate is missing”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Error: SSL certificate or key not found, you may need to run \`pnpm dlx @warp-drive/holodeck ensure-cert\`</span></span>
<span class="line"><span>    at getCertInfo (.../@warp-drive/diagnostic/dist-server/index.js:1254:67)</span></span>
<span class="line"><span>    at launch (.../@warp-drive/diagnostic/dist-server/index.js:1336:27)</span></span></code></pre></div><p>Both <code>@warp-drive/diagnostic</code> and holodeck serve over TLS, and both read the same certificate. Diagnostic starts first, so this is usually the first thing a machine without a certificate hits, and holodeck&#39;s banner never prints. Run the certificate step from <a href="./server-setup#trust-a-local-certificate">Server setup</a>.</p><p>Holodeck looks for <code>HOLODECK_SSL_CERT_PATH</code> and <code>HOLODECK_SSL_KEY_PATH</code>, and falls back to <code>$HOME/holodeck-localhost.pem</code> and <code>$HOME/holodeck-localhost-key.pem</code> when they are unset. The fallback is announced, not an error.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HOLODECK_SSL_CERT_PATH was not found in the current environment. Setting it to default value of /Users/you/holodeck-localhost.pem</span></span></code></pre></div><p>A run that prints those two lines and then serves normally is fine. Set the variables only when the certificate lives somewhere other than your home directory.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Could not determine a startup file for shell: /usr/bin/nu.</span></span>
<span class="line"><span>Holodeck falls back to /Users/you/holodeck-localhost.pem when the environment variables</span></span>
<span class="line"><span>are unset, so the certificate above already works as it is.</span></span></code></pre></div><p>This is information, not an error. <code>ensure-cert</code> issues the certificate before it looks at your shell, and it exits normally on a shell it cannot write a profile for. It goes on to print the two <code>export</code> lines in case you want them, but the certificate is already where holodeck looks.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkcert was not found on your PATH. Holodeck serves over TLS and uses mkcert to</span></span>
<span class="line"><span>issue a certificate for localhost.</span></span></code></pre></div><p><code>ensure-cert</code> checks for <code>mkcert</code> before it does anything else and exits with the install commands for each platform. Install it and run the command again.</p><h2 id="the-suite-starts-and-then-times-out" tabindex="-1">The suite starts and then times out <a class="header-anchor" href="#the-suite-starts-and-then-times-out" aria-label="Permalink to “The suite starts and then times out”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>⚠️  Diagnostic Watchdog: No browser reported in within 90s of launch. Assuming a hung browser and exiting.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   connections: 2 tcp, 1 tls handshakes</span></span>
<span class="line"><span>   requests served: 2</span></span>
<span class="line"><span>   websocket connections: 0</span></span>
<span class="line"><span>   server events: 870ms tlsClientError: socket hang up</span></span>
<span class="line"><span>   browsers: chrome#42 pid=90709 running</span></span></code></pre></div><p>Nothing before this names a cause. Holodeck&#39;s banner prints, the browser launches, and 90 seconds later the watchdog gives up and prints what the server saw in the meantime. A browser that fetched a page or two and never opened a websocket, as above, has usually been served a test bundle that does not exist. Check that <code>dist-test/index.html</code> is there, and run the suite through the command that builds first, which at this repository&#39;s root is <code>pnpm test</code>. The wait is <code>browserStartTimeout</code> in the launch config, 90 seconds by default.</p><h2 id="the-holodeck-server-is-not-running" tabindex="-1">The holodeck server is not running <a class="header-anchor" href="#the-holodeck-server-is-not-running" aria-label="Permalink to “The holodeck server is not running”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Promise rejected during &quot;…&quot;: Failed to fetch</span></span></code></pre></div><p>Every mock fails this way when nothing is listening on the host passed to <code>setConfig</code>. Safari words it as <code>Load failed</code>. Each test also fails from <code>afterEach</code> with a report that its mocks were never requested, which follows from the first error.</p><p>Check that whatever serves the suite also launched holodeck, and that its banner printed the port <code>setConfig</code> names. A suite opened from an app&#39;s dev server rather than from its test runner usually has no holodeck behind it. See <a href="/pr-preview/pr-11292/guides/the-manual/cookbook/holodeck-in-dev-mode">Holodeck in dev mode</a> for one way to start it there.</p><h2 id="the-port-was-taken" tabindex="-1">The port was taken <a class="header-anchor" href="#the-port-was-taken" aria-label="Permalink to “The port was taken”">​</a></h2><p>Holodeck binds the port it is given and never picks another, because the browser works out the mock server&#39;s URL by adding one to the test server&#39;s port. A conflict retries the same port a few times and then fails.</p><p>Stop whatever holds the port. A test run that was killed rather than shut down is the usual culprit.</p><h2 id="launched-from-the-wrong-directory" tabindex="-1">Launched from the wrong directory <a class="header-anchor" href="#launched-from-the-wrong-directory" aria-label="Permalink to “Launched from the wrong directory”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Package name not found in package.json</span></span></code></pre></div><p><code>launchProgram</code> reads <code>package.json</code> from the current working directory, and writes <code>.mock-cache</code> there too. Start the test runner from the test app&#39;s own directory.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./server-setup">Server setup</a></li><li><a href="./record-and-replay">Recording and replaying</a></li></ul>`,59)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};